#!/usr/bin/env python3
"""
make_dive.py  -  builds dive.json, a made-up 40-minute dive log for SharkCam.

*** MADE-UP DATA. No dive took place. The depth, light, visibility, temperature
*** and detections below are generated by this script for teaching.

The log has one row per second (1 frame per second) for 2,400 seconds.

Columns
-------
t_s           seconds since the start of the dive (0 to 2399)
depth_m       depth of the camera in metres
light         light level relative to the surface in full daylight (1.0 means surface)
visibility_m  how far the camera can see, in metres
temp_c        water temperature in degrees Celsius
detection     species id (see species.json) or null when the detector reports no species
confidence    detector confidence from 0 to 1, or null when detection is null

Physics used
------------
* Light falls roughly exponentially with depth: light = S(t) * exp(-Kd * depth).
  S(t) is the surface light, which wanders between 0.6 and 1.1 as clouds pass.
  Kd is the diffuse attenuation coefficient of the whole visible band (PAR), in
  1 per metre. Its mean is 0.34 per metre and it drifts between 0.22 and 0.55 along
  the dive as the water gets cloudier and clearer.
* Where the value comes from. No Mumbai measurement was found, so 0.34 is an
  assumption in the range of turbid coastal water. In coastal Baltic Sea water
  Kratzer et al. (2003, Ambio 32(8):577-585, doi:10.1639/0044-7447(2003)032[0577:ASAPZD]2.0.CO;2)
  measured Kd(490) of 0.33 to 0.92 per metre (mean 0.52) and found
  Kd(490) = 1.48 * Kd(PAR), which gives Kd(PAR) of about 0.22 to 0.62 per metre.
  Their data also show Kd(PAR) = 1.7 / Secchi depth (the Poole and Atkins relation of 1929).
* Visibility is taken as the Secchi-type depth, 1.7 / Kd, with 4% reading noise.
  With Kd = 0.34 per metre this is 5 m.
* Temperature. The surface value is the November mean sea surface temperature off
  Mumbai, 28.2 C (NOAA OISST v2.1, 2019 to 2023, see make_catch.py), with a fall of
  0.03 C per metre of depth (an assumption for well-mixed shallow water).
* depth.py uses colour-dependent attenuation. Its three coefficients average to 0.34
  per metre, the same value used here.

Detections
----------
Seven shark events are placed by hand (see EVENTS). Within an event the made-up
detector's confidence rises and falls like a smooth bump, and it is lower when the water is
cloudy or dark. The detector reports a species only when confidence reaches 0.30.
Three short false alarms (a rock ledge and shadows) are added so that chapters
can talk about wrong detections. They are listed in "events" with kind "false_alarm".

Run it with:   python -I make_dive.py     (needs numpy only)
"""

import json
import math
import os

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
rng = np.random.default_rng(4127)

N = 2400                      # frames, 1 per second
KD_MEAN = 0.34                # per metre, mean attenuation of the visible band
SECCHI_FACTOR = 1.7           # Kd = 1.7 / Secchi depth
T_SURFACE = 28.2              # deg C, November mean SST off Mumbai
DEPTH_TEMP_DROP = 0.03        # deg C per metre
THRESHOLD = 0.30              # the detector reports a species at or above this confidence

# Depth plan in (minutes, metres). The camera robot drifts down, works along a reef at
# 12 to 15 m, rises to 8 m and finishes with a slow ascent.
PLAN = [(0, 0), (1.5, 5), (4, 12), (10, 14), (15, 9), (20, 13), (26, 15), (32, 8), (36, 5), (38, 3), (40, 0)]

# Peak confidence of the made-up detector in good conditions.
BASE_CONF = {"spadenose": 0.90, "milk": 0.88, "bamboo": 0.82, "hammerhead": 0.93}

# Shark events: (start second, end second, species id).
EVENTS = [
    (312, 331, "spadenose"),
    (655, 684, "milk"),
    (842, 880, "bamboo"),
    (1258, 1297, "hammerhead"),
    (1531, 1546, "spadenose"),
    (1795, 1818, "milk"),
    (2105, 2140, "hammerhead"),
]
# False alarms: (start second, end second, species id the detector wrongly reports, what was there).
FALSE_ALARMS = [
    (470, 471, "bamboo", "a dark rock ledge"),
    (1102, 1102, "spadenose", "a passing shadow"),
    (1960, 1962, "milk", "a pale patch of sand"),
]


def ar1(n, phi, sd):
    """Slowly varying noise (autoregressive, order 1) with stationary sd."""
    x = np.zeros(n)
    innov = sd * math.sqrt(1 - phi ** 2)
    for i in range(1, n):
        x[i] = phi * x[i - 1] + rng.normal(0, innov)
    return x


def smooth(x, w):
    k = np.ones(w) / w
    pad = np.pad(x, (w // 2, w - 1 - w // 2), mode="edge")
    return np.convolve(pad, k, mode="valid")


def build():
    t = np.arange(N)
    keys_t = np.array([p[0] * 60 for p in PLAN], dtype=float)
    keys_d = np.array([p[1] for p in PLAN], dtype=float)
    depth = np.interp(t, keys_t, keys_d)
    depth = smooth(depth, 21) + ar1(N, 0.97, 0.12)
    depth = np.clip(depth, 0.0, None)
    depth[0] = 0.0
    depth[-1] = 0.0

    surface = np.clip(1.0 + 0.15 * ar1(N, 0.995, 1.0), 0.6, 1.1)
    kd = np.clip(KD_MEAN * (1.0 + 0.18 * ar1(N, 0.998, 1.0) * 1.5), 0.22, 0.55)
    light = surface * np.exp(-kd * depth) * np.exp(rng.normal(0, 0.02, N))
    vis = SECCHI_FACTOR / kd * np.exp(rng.normal(0, 0.04, N))
    temp = T_SURFACE - DEPTH_TEMP_DROP * depth + ar1(N, 0.99, 0.08)

    det = [None] * N
    conf = [None] * N
    events = []

    def quality(i):
        """How good the conditions are for the detector, from about 0.4 to 1."""
        v = min(1.0, vis[i] / 5.0) ** 0.5
        lg = min(1.0, max(0.4, (math.log10(max(light[i], 1e-6)) + 3.0) / 2.0))
        return v * lg

    for k, (a, b, sp) in enumerate(EVENTS, start=1):
        peak = 0.0
        shown = 0
        span = b - a
        for i in range(a, b + 1):
            u = (i - a) / span
            bump = 0.35 + 0.65 * math.sqrt(math.sin(math.pi * u)) if 0 < u < 1 else 0.35
            c = BASE_CONF[sp] * (0.45 + 0.55 * quality(i)) * bump + rng.normal(0, 0.03)
            c = float(min(0.99, max(0.05, c)))
            if c >= THRESHOLD:
                det[i] = sp
                conf[i] = round(c, 3)
                shown += 1
                peak = max(peak, c)
        events.append({"id": "E%d" % k, "kind": "shark", "species": sp, "start_s": a, "end_s": b,
                       "frames_with_detection": shown, "peak_confidence": round(peak, 3),
                       "mean_depth_m": round(float(depth[a:b + 1].mean()), 1),
                       "mean_visibility_m": round(float(vis[a:b + 1].mean()), 1)})

    for k, (a, b, sp, what) in enumerate(FALSE_ALARMS, start=1):
        peak = 0.0
        for i in range(a, b + 1):
            c = float(rng.uniform(0.32, 0.43))
            det[i] = sp
            conf[i] = round(c, 3)
            peak = max(peak, c)
        events.append({"id": "F%d" % k, "kind": "false_alarm", "species": sp, "start_s": a, "end_s": b,
                       "frames_with_detection": b - a + 1, "peak_confidence": round(peak, 3),
                       "mean_depth_m": round(float(depth[a:b + 1].mean()), 1),
                       "mean_visibility_m": round(float(vis[a:b + 1].mean()), 1),
                       "what_was_there": what})

    def sig(x, n=4):
        return float("%.*g" % (n, x))

    rows = [[int(i), round(float(depth[i]), 2), sig(light[i]), round(float(vis[i]), 2),
             round(float(temp[i]), 2), det[i], conf[i]] for i in range(N)]
    events.sort(key=lambda e: e["start_s"])
    return rows, events, depth, light, vis, temp


def main():
    rows, events, depth, light, vis, temp = build()
    doc = {
        "about": "Made-up dive log for teaching, not a record of an actual dive. Generated by make_dive.py. "
                 "One row per second for 40 minutes at 1 frame per second.",
        "columns": ["t_s", "depth_m", "light", "visibility_m", "temp_c", "detection", "confidence"],
        "units": {"t_s": "seconds", "depth_m": "metres", "light": "relative to surface, 1.0 = full daylight at the surface",
                  "visibility_m": "metres", "temp_c": "degrees Celsius",
                  "detection": "species id from species.json or null", "confidence": "0 to 1 or null"},
        "n_frames": N,
        "fps": 1,
        "duration_s": N,
        "month": 11,
        "attenuation": {
            "kd_mean_per_m": KD_MEAN,
            "kd_range_per_m": [0.22, 0.55],
            "light_rule": "light = surface(t) * exp(-Kd(t) * depth)",
            "visibility_rule": "visibility = 1.7 / Kd (Secchi-type depth, 4% noise)",
            "source": "Assumption in the range of turbid coastal water. Kratzer et al. (2003), Ambio 32(8):577-585, "
                      "doi:10.1639/0044-7447(2003)032[0577:ASAPZD]2.0.CO;2 report Kd(490) of 0.33 to 0.92 per metre "
                      "in coastal Baltic Sea water and Kd(490) = 1.48 * Kd(PAR). No Mumbai value was found.",
        },
        "detector": "A made-up detector. It reports a species when confidence reaches %.2f." % THRESHOLD,
        "events": events,
        "rows": rows,
    }
    with open(os.path.join(HERE, "dive.json"), "w", encoding="utf8") as f:
        json.dump(doc, f, separators=(",", ":"), ensure_ascii=False)
    print("wrote dive.json,", len(rows), "rows,", len(events), "events")
    print("max depth %.1f m, mean light %.4f, light range %.5f to %.3f" % (depth.max(), light.mean(), light.min(), light.max()))
    print("visibility %.1f to %.1f m; temp %.2f to %.2f" % (vis.min(), vis.max(), temp.min(), temp.max()))
    for e in events:
        print(e)


if __name__ == "__main__":
    main()
